function shareIntent(text,url){const query=new URLSearchParams({text:text.trim()+"\n\n"+SHARE_ATTRIBUTION,url});return "https://x.com/intent/tweet?"+query;}

return {EXTRA_COPY,ABOUT_COPY,STICKER_RU,EGG_RU,SHARE_TEMPLATES,SHARE_ATTRIBUTION,shareIntent};
