Object.assign(copy.ru,{halloween:"Хэллоуин",descHalloween:"Хэллоуинская коллекция Pocket Dragons",hwBlinky:"Блинки",hwPinky:"Пинки",hwElements:"Элементы",hwBackgrounds:"Фоны"});
