const t=key=>copy[lang][key]||key;
const escape=value=>String(value).replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
let catalog=[],assets=new Map(),images=new Map(),pending=new Map(),thumbImages=new Map(),thumbAssets=new Map(),templatePreviews=new Map();
let state=makeTemplate("gm"),history,selected=state.objects[1].id,tab="templates",hero="blinky",templateFilter="all",halloweenGroup="blinky",drag=null,layerDrag=null,currentHint="tip",toastTimer,saveTimer,refreshTicket=0,previewURL=null;
let previewFrameId=0,previewLastFrame=0;
const canvas=$("#artboard");
const selectedObject=()=>state.objects.find(o=>o.id===selected);
function assetName(a){
  if(!a)return "";
  if(a.category==="characters"){const match=a.id.match(/^(blinky|pinky)-\d+-(.*)$/);return t(match[1]+"Name")+" · "+t(match[2]);}
  if(a.category==="eggs")return lang==="ru"?(EGG_RU[a.id.replace("egg-","")]||a.name):a.id.replace("egg-","").replace(/^./,c=>c.toUpperCase());
  if(a.category==="stickers")return lang==="ru"?STICKER_RU[a.id.replace("blinky-sticker-","")]||a.name:a.name.replace(/^Blinky, /,"");
  if(a.category==="badges")return a.name.replace(" badge","");
  return copy[lang][a.id]||a.name;
}
const objectName=o=>o.type==="text"?(o.text.replace(/\n/g," ").trim()||t("textName")):assetName(assets.get(o.asset));
function toast(message){clearTimeout(toastTimer);$("#toast").textContent=message;$("#toast").classList.add("visible");toastTimer=setTimeout(()=>$("#toast").classList.remove("visible"),3000);}
function showHint(key,announce=false){currentHint=key;$("#context-hint").textContent=t(key);if(announce)toast(t(key));}
function persist(){
  clearTimeout(saveTimer);
  saveTimer=setTimeout(()=>{
    try{localStorage.setItem("keeper-studio-draft-v1",JSON.stringify(state));$("#save-status").textContent=t("saved");}
    catch{$("#save-status").textContent=t("saveFail");}
  },300);
}
function paint(){render(canvas,state,{assets,images,selected});}
const animationEffects=[
  ["float","↟","Парение","Float","smooth"],
  ["sway","↶","Покачивание","Sway","smooth"],
  ["pulse","◉","Пульс","Pulse","smooth"],
  ["breathe","♡","Дыхание","Breathe","smooth"],
  ["rotate","⟳","Вращение","Rotate","smooth"],
  ["bounce","↥","Прыжок","Bounce","dynamic"],
  ["shake","≋","Дрожание","Shake","dynamic"],
  ["swing","↔","Маятник","Swing","dynamic"],
  ["wiggle","〰","Виляние","Wiggle","dynamic"],
  ["hop","⌃","Подскок","Hop","dynamic"],
  ["fade","◐","Появление","Fade","movement"],
  ["slide","→","Сдвиг","Slide","movement"],
  ["zoom","⊕","Увеличение","Zoom","movement"],
  ["pop","✦","Вспышка","Pop","movement"],
  ["drift","↗","Дрейф","Drift","movement"]
];
let animationOpen=false;
function syncAnimationMenu(){
  const o=selectedObject(),ru=document.documentElement.lang!=="en";
  $("#animation-label").textContent=ru?"Анимация":"Animate";
  $("#animation-title").textContent=ru?"✨ Анимация объекта":"✨ Object animation";
  $("#animation-toggle").classList.toggle("has-animation",!!o?.animation);
  $("#animation-toggle").disabled=!o;
  $("#animation-toggle").setAttribute("aria-expanded",String(animationOpen&&!!o));
  $("#animation-menu").hidden=!animationOpen||!o;
  const groupNames={smooth:ru?"Плавные":"Smooth",dynamic:ru?"Динамичные":"Dynamic",movement:ru?"Появление и движение":"Appear & move"};
  $("#animation-grid").innerHTML=Object.entries(groupNames).map(([group,title])=>`<div class="animation-group"><div class="animation-group-title">${title}</div><div class="animation-group-items">${animationEffects.filter(effect=>effect[4]===group).map(([id,symbol,name,en])=>`<button type="button" class="animation-effect ${o?.animation===id?"active":""}" data-animation="${id}" aria-pressed="${o?.animation===id}"><span>${symbol}</span>${ru?name:en}${o?.animation===id?" ✓":""}</button>`).join("")}</div></div>`).join("");
  $("#animation-speed-label").textContent=ru?"Скорость анимации":"Animation speed";
  for(const btn of document.querySelectorAll("[data-animation-speed]")){
    const value=btn.dataset.animationSpeed;
    btn.textContent=ru?({slow:"Медленно",normal:"Обычно",fast:"Быстро"}[value]):({slow:"Slow",normal:"Normal",fast:"Fast"}[value]);
    btn.classList.toggle("active",!!o?.animation&&(o.animationSpeed||"normal")===value);
    btn.disabled=!o?.animation;
    btn.setAttribute("aria-pressed",String(!!o?.animation&&(o.animationSpeed||"normal")===value));
  }
  $("#animation-clear").textContent=ru?"✕ Убрать анимацию":"✕ Remove animation";
  $("#animation-clear").disabled=!o?.animation;
}
$("#animation-toggle").addEventListener("click",()=>{animationOpen=!animationOpen;syncAnimationMenu();});
$("#animation-close").addEventListener("click",()=>{animationOpen=false;syncAnimationMenu();});
$("#animation-grid").addEventListener("click",e=>{const btn=e.target.closest("[data-animation]");const o=selectedObject();if(!btn||!o)return;o.animation=btn.dataset.animation;o.animationSpeed ||= "normal";commit();syncAnimationMenu();});
$("#animation-speed").addEventListener("click",e=>{
  const btn=e.target.closest("[data-animation-speed]"),o=selectedObject();
  if(!btn||!o?.animation)return;
  o.animationSpeed=btn.dataset.animationSpeed;commit();syncAnimationMenu();
});
$("#animation-clear").addEventListener("click",()=>{const o=selectedObject();if(!o)return;delete o.animation;delete o.animationSpeed;commit();syncAnimationMenu();});
(function animateFrame(){if(state.objects.some(o=>o.animation)&&!document.hidden)paint();requestAnimationFrame(animateFrame);})();
function fitCanvas(){
  const area=$("#canvas-area"),{w,h}=FORMATS[state.format];
  const padding=innerWidth<=620?40:48;
  const availableW=Math.max(10,area.clientWidth-padding),availableH=Math.max(10,area.clientHeight-padding);
  const ratio=Math.min(availableW/w,availableH/h);
  $("#canvas-frame").style.width=Math.floor(w*ratio)+"px";$("#canvas-frame").style.height=Math.floor(h*ratio)+"px";paint();
}
function updateToolbar(){
  $("#undo").disabled=!history?.canUndo;$("#redo").disabled=!history?.canRedo;
  $("#dimensions").textContent=FORMATS[state.format].w+" × "+FORMATS[state.format].h+" px";
  $("#format-picker").innerHTML=Object.entries(FORMATS).map(([id,f])=>'<button type="button" data-format="'+id+'" class="'+(state.format===id?"active":"")+'" aria-pressed="'+(state.format===id)+'">'+f.label+'</button>').join("");
  $("#transparent").checked=state.transparent;
}
function commit({inspector=true}={}){
  history.push(state);persist();paint();updateToolbar();if(inspector)renderInspector();syncAnimationMenu();
}
function loadImage(id,thumb=false){
  const cache=thumb?thumbImages:images,key=(thumb?"thumb:":"full:")+id;
  if(cache.has(id))return Promise.resolve(cache.get(id));
  if(pending.has(key))return pending.get(key);
  const a=assets.get(id);if(!a)return Promise.reject(Error("Missing artwork "+id));
  const promise=new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{cache.set(id,im);if(thumb){thumbAssets.set(id,{...a,box:[0,0,im.naturalWidth,im.naturalHeight]});}else if(a.category==="stickers"){a.box=[0,0,im.naturalWidth,im.naturalHeight];}resolve(im);};im.onerror=()=>reject(Error("Artwork unavailable"));im.src=thumb?a.thumb:a.src;}).finally(()=>pending.delete(key));
  pending.set(key,promise);return promise;
}
function usedAssets(s){return [...new Set([...s.objects.filter(o=>o.type==="image").map(o=>o.asset),...(assets.has(s.background)&&!s.transparent?[s.background]:[])])];}
async function ensureImages(s,thumb=false){await Promise.all(usedAssets(s).map(id=>loadImage(id,thumb)));}
function trimCache(){
  const pinned=new Set(usedAssets(state));
  for(const id of images.keys()){if(images.size<=10)break;if(!pinned.has(id))images.delete(id);}
}
async function refresh(){
  const ticket=++refreshTicket;
  const missing=usedAssets(state).some(id=>!images.has(id));
  $("#loading").hidden=!missing;
  try{await ensureImages(state);if(ticket!==refreshTicket)return;trimCache();paint();fitCanvas();renderInspector();updateToolbar();}
  catch(error){if(ticket===refreshTicket)toast(t("imageError"));}
  finally{if(ticket===refreshTicket)$("#loading").hidden=true;}
}
function renderInspector(){
  const o=selectedObject(),host=$("#selection-properties");
  if(!o)host.innerHTML='<div class="empty-selection">'+escape(t("selectHint"))+'</div>';
  else{
    const isText=o.type==="text";
    let html='<div class="selected-name"><span>'+icon(isText?"text":"dragons")+'</span><span>'+escape(isText?t("textName"):objectName(o))+'</span></div><p class="selection-tip">'+escape(t(isText?"hintText":"hintImage"))+'</p>';
    if(isText){
      html+='<label class="field-label" for="text-value">'+escape(t("textContent"))+'</label><textarea id="text-value" maxlength="800" rows="3">'+escape(o.text)+'</textarea>';
      html+='<div class="text-controls"><select id="font-choice" aria-label="'+escape(t("font"))+'"><option value="serif" '+(o.font==="serif"?"selected":"")+'>'+escape(t("serif"))+'</option><option value="sans" '+(o.font==="sans"?"selected":"")+'>'+escape(t("sans"))+'</option></select><div class="align-buttons">'+["left","center","right"].map(a=>'<button data-align="'+a+'" class="'+(o.align===a?"active":"")+'" title="'+escape(t(a))+'" aria-label="'+escape(t(a))+'" aria-pressed="'+(o.align===a)+'">'+icon(a)+'</button>').join("")+'</div></div>';
      html+=rangeControl("size",t("textSize"),Math.round(o.size*FORMATS[state.format].w),Math.round(.005*FORMATS[state.format].w),Math.round(.22*FORMATS[state.format].w),"px");
      html+=rangeControl("width",t("textWidth"),Math.round(o.w*100),10,150,"%");
      html+='<label class="field-label" for="color-choice">'+escape(t("color"))+'</label><div class="color-row">'+["#352330","#fff0dc","#e9bc8c","#f3adc4","#cab6ec","#ffffff"].map(c=>'<button class="color-swatch '+(o.color===c?"active":"")+'" style="background:'+c+'" data-color="'+c+'" aria-label="'+c+'" aria-pressed="'+(o.color===c)+'"></button>').join("")+'<input id="color-choice" type="color" value="'+o.color+'" aria-label="'+escape(t("color"))+'"></div>';
    }else html+=rangeControl("width",t("objectSize"),Math.round(o.w*100),4,150,"%");
    html+=rangeControl("rotation",t("rotation"),Math.round(o.rotation),-180,180,"°");
    html+='<div class="object-actions">'+["down","up","duplicate","trash"].map(action=>'<button data-action="'+action+'" class="'+(action==="trash"?"danger":"")+'" title="'+escape(t(action))+'" aria-label="'+escape(t(action))+'">'+icon(action)+'</button>').join("")+'</div>';
    html+='<div class="depth-actions" aria-label="'+escape(t("layerOrder"))+'">'+["back","front"].map(action=>'<button data-action="'+action+'" title="'+escape(t(action))+'">'+escape(t(action))+'</button>').join("")+'</div>';
    host.innerHTML=html;
    const index=state.objects.indexOf(o);host.querySelector('[data-action="down"]').disabled=index===0;host.querySelector('[data-action="up"]').disabled=index===state.objects.length-1;
    host.querySelector('[data-action="back"]').disabled=index===0;host.querySelector('[data-action="front"]').disabled=index===state.objects.length-1;
  }
  renderLayers();
}
function rangeControl(id,label,value,min,max,unit){return '<label class="range-label" for="object-'+id+'"><span>'+escape(label)+'</span><output id="output-'+id+'">'+value+unit+'</output></label><input id="object-'+id+'" type="range" min="'+min+'" max="'+max+'" value="'+value+'" data-property="'+id+'" data-unit="'+unit+'">';}
function renderLayers(){
  $("#layer-count").textContent=state.objects.length;
  $("#layers").innerHTML=state.objects.length?[...state.objects].reverse().map(o=>'<div class="layer-row" data-layer="'+o.id+'"><button class="layer '+(o.id===selected?"active":"")+'" data-select="'+o.id+'" aria-pressed="'+(o.id===selected)+'">'+(o.type==="text"?'<span class="layer-thumb layer-type">T</span>':'<img class="layer-thumb" src="'+assets.get(o.asset).thumb+'" alt="">')+'<span class="layer-label">'+escape(objectName(o))+'</span></button><button class="layer-handle" data-layer-drag="'+o.id+'" title="'+escape(t("dragLayer"))+'" aria-label="'+escape(t("dragLayer")+": "+objectName(o))+'">'+icon("grip")+'</button></div>').join(""):'<p class="empty-layer">'+escape(t("emptyLayer"))+'</p>';
}
function renderLibrary(){
  $("#library-tabs").innerHTML=["templates","dragons","eggs","badges","stickers","decor","backgrounds"].map(id=>'<button class="library-tab '+(id===tab?"active":"")+'" data-tab="'+id+'" aria-pressed="'+(id===tab)+'">'+(id==="halloween"?"🎃":id==="dragons"?'<img src="'+assets.get("blinky-10-portrait").thumb+'" alt="">':id==="eggs"?'<img src="'+assets.get("egg-pink").thumb+'" alt="">':icon(id))+'<span>'+escape(t(id))+'</span></button>').join("");
  $("#halloween-tab").classList.toggle("active",tab==="halloween");
  $("#halloween-tab").setAttribute("aria-pressed",String(tab==="halloween"));
  $("#halloween-tab-label").textContent=t("halloween");
  $("#library-description").textContent=t("desc"+tab[0].toUpperCase()+tab.slice(1));
  $("#asset-filters").innerHTML=tab==="dragons"?["blinky","pinky"].map(id=>'<button class="filter '+(hero===id?"active":"")+'" data-hero="'+id+'" aria-pressed="'+(hero===id)+'">'+t(id+"Name")+'</button>').join(""):tab==="templates"?["all",...Object.keys(TEMPLATE_CATEGORIES)].map(id=>'<button class="filter '+(templateFilter===id?"active":"")+'" data-template-group="'+id+'" aria-pressed="'+(templateFilter===id)+'">'+escape(t("group"+id[0].toUpperCase()+id.slice(1)))+'</button>').join(""):"";
  if(tab==="halloween")$("#asset-filters").innerHTML=["blinky","pinky","decor","backgrounds"].map(id=>'<button class="filter '+(halloweenGroup===id?"active":"")+'" data-halloween-group="'+id+'" aria-pressed="'+(halloweenGroup===id)+'">'+escape(t(({blinky:"hwBlinky",pinky:"hwPinky",decor:"hwElements",backgrounds:"hwBackgrounds"})[id]))+'</button>').join("");
  const grid=$("#asset-grid");
  grid.classList.toggle("templates-grid",tab==="templates");
  if(tab==="halloween"){
    const group=halloweenGroup;
    const visible=HALLOWEEN_ASSETS.filter(a=>a.hwGroup===(group==="backgrounds"?"backgrounds":group));
    const shown=group==="backgrounds"?visible.filter(a=>a.hwFormat===state.format):visible;
    grid.innerHTML=shown.map(a=>'<button class="asset-card '+(group==="backgrounds"?'template':'')+'" '+(group==="backgrounds"?'data-background':'data-asset')+'="'+a.id+'" title="'+escape(a.name)+'"><img loading="lazy" src="'+a.thumb+'" alt=""><span>'+escape(a.name.replace(/\s(?:16X9|9X16|1X1)$/i,''))+'</span></button>').join("");
  }else if(tab==="templates"){
    const visible=TEMPLATE_IDS.filter(id=>templateFilter==="all"||TEMPLATE_CATEGORIES[templateFilter].includes(id));
    grid.innerHTML=visible.map(id=>'<button class="asset-card template '+(state.template===id?"active":"")+'" data-template="'+id+'"><img src="'+(templatePreviews.get(id)||"favicon.svg")+'" alt=""><span class="template-format">'+FORMATS[makeTemplate(id).format].label+'</span><span>'+escape(t(id))+'</span></button>').join("");
  }else if(tab==="backgrounds"){
    grid.innerHTML=["white","ember","rose","midnight"].map(id=>'<button class="asset-card template" data-background="'+id+'"><img src="'+templatePreviews.get("bg-"+id)+'" alt=""><span>'+escape(t(id))+'</span></button>').join("")+catalog.filter(a=>a.category==="scenes"&&a.collection!=="halloween").map(a=>'<button class="asset-card template" data-background="'+a.id+'"><img src="'+a.thumb+'" alt=""><span>'+escape(assetName(a))+'</span></button>').join("");
  }else{
    const category=({dragons:"characters",eggs:"eggs",badges:"badges",stickers:"stickers"})[tab]||null;
    grid.innerHTML=catalog.filter(a=>category?a.category===category&&(tab!=="dragons"||a.id.startsWith(hero)):!["characters","eggs","scenes","badges","stickers"].includes(a.category)).map(a=>'<button class="asset-card" data-asset="'+a.id+'" title="'+escape(assetName(a))+'"><span class="add-badge" aria-hidden="true">+</span><img loading="lazy" src="'+a.thumb+'" alt=""><span>'+escape(assetName(a))+'</span></button>').join("");
  }
}
