$("#undo").addEventListener("click",()=>stepHistory("undo"));$("#redo").addEventListener("click",()=>stepHistory("redo"));
document.addEventListener("click",event=>{const button=event.target.closest("[data-language]");if(!button||button.dataset.language===lang)return;lang=button.dataset.language;try{localStorage.setItem("keeper-studio-language",lang);}catch{}if(history)localize();else{document.documentElement.lang=lang;opening.localize();}});
for(const selector of ["#about","#credits-link"])$(selector).addEventListener("click",()=>$("#about-dialog").showModal());
$("#help").addEventListener("click",()=>$("#help-dialog").showModal());
document.addEventListener("keydown",event=>{
  if(opening.active||!history)return;
  const editing=event.target.matches("input,textarea,select,[contenteditable=true]");
  if(event.key==="Escape"&&drag)endDrag();
  if(event.target.closest("dialog"))return;
  if(!editing&&(event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="z"){event.preventDefault();stepHistory(event.shiftKey?"redo":"undo");return;}
  if(editing)return;
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="y"){event.preventDefault();stepHistory("redo");return;}
  if(event.key==="Delete"||event.key==="Backspace"){if(selectedObject()){event.preventDefault();performAction("trash");}return;}
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="d"){if(selectedObject()){event.preventDefault();performAction("duplicate");}return;}
  if(event.target!==canvas)return;
  const o=selectedObject();if(!o)return;const amount=event.shiftKey?.02:.003;
  if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(event.key)){event.preventDefault();if(event.key==="ArrowLeft")o.x-=amount;if(event.key==="ArrowRight")o.x+=amount;if(event.key==="ArrowUp")o.y-=amount;if(event.key==="ArrowDown")o.y+=amount;o.x=clamp(o.x,-.5,1.5);o.y=clamp(o.y,-.5,1.5);commit();}
});
async function exportCanvas(){await ensureImages(state);const output=document.createElement("canvas");render(output,state,{assets,images,selection:false});return output;}
// Header download menu: existing PNG dialog and existing live Preview exporters are reused.
function localizeDownloadMenu(){
  const ru=lang!=="en";
  const labels=ru?{
    main:"Скачать",png:"Скачать PNG",mp4:"Скачать MP4",gif:"Скачать GIF",
    pngHint:"Изображение",mp4Hint:"Видео · 3 / 5 / 10 сек",gifHint:"Анимация · 3 / 5 сек"
  }:{main:"Download",png:"Download PNG",mp4:"Download MP4",gif:"Download GIF",
    pngHint:"Image",mp4Hint:"Video · 3 / 5 sec / 10 sec",gifHint:"Animation · 3 / 5 sec"};
  for(const [id,key] of Object.entries({"download-menu-label":"main","download-png-label":"png","download-mp4-label":"mp4","download-gif-label":"gif","download-png-hint":"pngHint","download-mp4-hint":"mp4Hint","download-gif-hint":"gifHint"})){
    const el=document.getElementById(id);if(el)el.textContent=labels[key];
  }
}
function localizePreviewControls(){
  const en=lang==="en";
  const pngButton=document.getElementById("preview-download-png");
  if(pngButton)pngButton.textContent=en?"Download PNG":"Скачать PNG";
  const gifButton=document.getElementById("download-gif");
  const gifLabel=document.getElementById("gif-duration-label");
  const gifQuality=document.getElementById("gif-quality");
  const gifDuration=document.getElementById("gif-duration");
  if(gifButton)gifButton.textContent=en?"Download GIF":"Скачать GIF";
  if(gifLabel)gifLabel.textContent=en?"GIF duration":"Длительность GIF";
  if(gifQuality){gifQuality.setAttribute("aria-label",en?"GIF quality":"Качество GIF");
    gifQuality.options[0].textContent="Discord Optimized";
    gifQuality.options[1].textContent="High Quality";}
  if(gifDuration)for(const option of gifDuration.options)option.textContent=option.value+(en?" sec":" сек");
  const previewCanvas=document.getElementById("preview-canvas");
  if(previewCanvas)previewCanvas.setAttribute("aria-label",en?"Animated preview of your composition":"Анимированный предпросмотр композиции");
  if(typeof refreshMP4Controls==="function")refreshMP4Controls();
  const gifStatus=document.getElementById("gif-export-status");
  if(gifStatus && gifStatus.dataset.state==="finished")gifStatus.textContent=(en?"GIF saved: ":"GIF готов: ")+gifStatus.dataset.size+(en?" MB":" МБ");
  else if(gifStatus && gifStatus.dataset.state==="encoding")gifStatus.textContent=en?"Encoding GIF…":"Кодирование GIF…";
  else if(gifStatus && gifStatus.dataset.state==="error")gifStatus.textContent=(en?"GIF error: ":"Ошибка GIF: ")+(gifStatus.dataset.error||"");
}
