async function chooseDraft(draft){
  const dialog=$("#draft-dialog");
  const useDraft=await new Promise(resolve=>{
    const done=value=>{dialog.close();resolve(value);};
    $("#continue-draft").addEventListener("click",()=>done(true),{once:true});$("#new-draft").addEventListener("click",()=>done(false),{once:true});
    dialog.addEventListener("cancel",event=>{event.preventDefault();done(true);},{once:true});dialog.showModal();
  });
  if(useDraft){state=draft;selected=state.objects.find(o=>o.type==="text"&&o.font==="serif")?.id||state.objects.find(o=>o.type==="text")?.id||null;toast(t("restored"));}
  else{state=makeTemplate("gm");selected=state.objects.find(o=>o.type==="text"&&o.font==="serif")?.id||state.objects.find(o=>o.type==="text")?.id||null;}
  history=new History(state);renderLibrary();updateToolbar();await refresh();
}


async function init(){
  try{
    catalog=[...__assetCatalog,...HALLOWEEN_ASSETS];assets=new Map(catalog.map(a=>[a.id,a]));
    let savedDraft=null;try{const draft=localStorage.getItem("keeper-studio-draft-v1");if(draft)savedDraft=sanitizeState(JSON.parse(draft),new Set(assets.keys()));}catch{}
    history=new History(state);localize();updateToolbar();await refresh();
    const openingReady=opening.finished.then(async()=>{if(savedDraft)await chooseDraft(savedDraft);persist();});
    const output=document.createElement("canvas");
    for(const id of TEMPLATE_IDS){const s=makeTemplate(id);await ensureImages(s,true);render(output,s,{assets:thumbAssets,images:thumbImages,selection:false,scale:.24});templatePreviews.set(id,output.toDataURL("image/webp",.86));}
    for(const id of ["white","ember","rose","midnight"]){const s=makeTemplate("blank");s.background=id;render(output,s,{assets:thumbAssets,images:thumbImages,selection:false,scale:.24});templatePreviews.set("bg-"+id,output.toDataURL("image/webp",.86));}
    renderLibrary();await openingReady;
  }catch(error){$("#loading").hidden=true;toast(t("imageError"));$("#library-description").textContent=t("imageError");}
}
init();

